-- Radical detail: position, origin, usage and a Han-Viet mnemonic for every row in 03-radicals.sql.
-- Needs the four columns from 04-component-detail.sql. Safe to rerun; only fills the new columns.

UPDATE components AS c SET
  position    = v.position,
  origin_vi   = v.origin_vi,
  usage_vi    = v.usage_vi,
  mnemonic_vi = v.mnemonic_vi
FROM (VALUES
  ('一', NULL, 'Một nét ngang, chỉ số một và ý "duy nhất, toàn bộ".', 'Làm nét nền trong 三 tam, 上 thượng, 下 hạ.', '"Nhất" như đệ nhất, thống nhất, nhất trí.'),
  ('丨', NULL, 'Một nét sổ thẳng từ trên xuống, nghĩa là xuyên suốt.', 'Hiếm đứng riêng, thấy trong 中 trung, 丰 phong.', '"Cổn" chỉ nét sổ, ít dùng trong tiếng Việt.'),
  ('丶', NULL, 'Một dấu chấm, vốn vẽ ngọn lửa đèn.', 'Làm nét điểm trong 主 chủ, 丸 hoàn.', '"Chủ" như chủ nhân, có chấm trên đầu 王 thành 主.'),
  ('丿', NULL, 'Nét phẩy nghiêng từ phải xuống trái.', 'Làm nét trong 乃 nãi, 久 cửu, 千 thiên.', '"Phiệt" là tên nét, chỉ dùng khi học chữ.'),
  ('乙', NULL, 'Vẽ hình cong queo như mầm cây uốn mình, mượn làm can thứ hai.', 'Thấy trong 九 cửu, 也 dã; biến thể 乚.', '"Ất" như can chi giáp ất bính đinh.'),
  ('亅', NULL, 'Nét sổ có móc câu ở chân.', 'Thấy trong 了 liễu, 事 sự, 予 dư.', '"Quyết" là tên nét móc, ít dùng riêng.'),
  ('二', NULL, 'Hai nét ngang, chỉ số hai.', 'Thấy trong 元 nguyên, 云 vân, 五 ngũ.', '"Nhị" như nhị phân, độc nhất vô nhị.'),
  ('亠', 'top', 'Một chấm trên một ngang, vốn là phần nắp đậy ở đỉnh chữ.', 'Luôn nằm trên đầu: 京 kinh, 亮 lượng, 交 giao.', '"Đầu" như đầu đề, đứng trên đầu chữ.'),
  ('人', NULL, 'Vẽ người nhìn nghiêng, hai nét là chân đang bước.', 'Đứng riêng là 人; vào chữ thường đổi thành 亻.', '"Nhân" như nhân loại, nhân viên, cá nhân.'),
  ('儿', 'bottom', 'Vẽ hai chân người, phần dưới của chữ 人.', 'Luôn ở chân chữ: 兄 huynh, 先 tiên, 光 quang.', '"Nhân" ở đây là người, không phải "nhi" trẻ con.'),
  ('入', 'top', 'Vẽ mũi nhọn chĩa vào, nghĩa là đi vào.', 'Thấy trong 内 nội, 全 toàn.', '"Nhập" như nhập khẩu, nhập học, thu nhập.'),
  ('八', NULL, 'Hai nét tách ra hai bên, gốc nghĩa là chia; mượn làm số tám.', 'Thấy trong 分 phân, 公 công, 兴 hưng.', '"Bát" như bát giác, bát quái, lục bát.'),
  ('冂', 'enclose', 'Vẽ khung bao ba mặt, hở phía dưới.', 'Bao bên ngoài: 内 nội, 冊 sách, 再 tái.', '"Quynh" chỉ vùng biên xa, nay chỉ còn là khung.'),
  ('冖', 'top', 'Vẽ tấm khăn phủ trùm lên đồ vật.', 'Nằm trên đầu: 军 quân, 写 tả.', '"Mịch" là trùm khăn, khác 冫 băng hai chấm.'),
  ('冫', 'left', 'Vẽ hai vệt nước đá đóng băng.', 'Chữ có 冫 thường lạnh: 冷 lãnh, 冰 băng, 冬 đông.', '"Băng" như băng giá, băng tuyết.'),
  ('几', NULL, 'Vẽ cái ghế nhỏ hoặc bàn thấp có hai chân.', 'Thấy trong 凡 phàm, 凭 bằng; giản thể dùng làm 幾 kỷ.', '"Kỷ" như án kỷ, bàn ghế.'),
  ('凵', 'enclose', 'Vẽ cái hố hoặc miệng há ra, hở phía trên.', 'Bao phía dưới: 凶 hung, 出 xuất.', '"Khảm" như hố sâu, quẻ Khảm là nước.'),
  ('刀', NULL, 'Vẽ con dao có lưỡi và cán.', 'Đứng riêng là 刀; bên phải chữ đổi thành 刂.', '"Đao" như đại đao, đao kiếm, dao kéo.'),
  ('力', 'right', 'Vẽ cánh tay gân guốc đang dùng sức, hoặc cái cày.', 'Chữ có 力 thường chỉ sức: 动 động, 加 gia, 男 nam.', '"Lực" như sức lực, nỗ lực, năng lực.'),
  ('勹', 'enclose', 'Vẽ người cúi khom ôm lấy vật, bao từ trên xuống.', 'Bao bên ngoài: 包 bao, 句 cú, 勿 vật.', '"Bao" như bao bọc, bao vây.'),
  ('匕', NULL, 'Vẽ cái thìa múc thức ăn; cũng là hình người nằm ngược.', 'Thấy trong 化 hóa, 北 bắc, 比 tỷ.', '"Chủy" như chủy thủ là dao găm ngắn.'),
  ('匚', 'enclose', 'Vẽ cái hộp hoặc tủ đựng đồ, hở bên phải.', 'Bao bên trái: 区 khu, 匹 thất, 医 y.', '"Phương" ở đây là cái hộp, không phải vuông.'),
  ('匸', 'enclose', 'Vẽ vật che đậy kín, hở bên phải.', 'Rất hiếm, thấy trong 匿 nặc, 區 khu.', '"Hệ" là che giấu, như ẩn nặc.'),
  ('十', NULL, 'Vẽ hai nét giao nhau, chỉ đủ bốn phương, nghĩa là mười.', 'Thấy trong 古 cổ, 协 hiệp, 直 trực.', '"Thập" như thập niên, thập toàn thập mỹ.'),
  ('卜', 'right', 'Vẽ vết nứt trên mai rùa khi nung để bói.', 'Thấy trong 外 ngoại, 占 chiêm, 卦 quái.', '"Bốc" như bói toán, bốc quẻ.'),
  ('卩', 'right', 'Vẽ người quỳ gối; cũng là thẻ tre làm tin.', 'Nằm bên phải: 印 ấn, 却 khước, 卷 quyển.', '"Tiết" như tiết tháo, đốt tre có mấu.'),
  ('厂', 'enclose', 'Vẽ vách núi nhô ra che được người ở dưới.', 'Bao góc trên trái: 原 nguyên, 厚 hậu, 历 lịch.', '"Hán" là sườn núi; giản thể mượn làm 廠 xưởng.'),
  ('厶', NULL, 'Vẽ cánh tay khoanh lại giữ của riêng cho mình.', 'Thấy trong 去 khứ, 参 tham, 私 tư.', '"Khư" là riêng tư, gốc của chữ 私 tư.'),
  ('又', 'right', 'Vẽ bàn tay phải, nghĩa gốc là tay.', 'Chữ có 又 thường liên quan tay: 取 thủ, 友 hữu, 反 phản.', '"Hựu" nghĩa là lại nữa, nhưng hình vẽ là bàn tay.'),
  ('口', NULL, 'Vẽ cái miệng mở ra.', 'Chữ có 口 liên quan miệng, ăn nói: 吃 ngật, 叫 khiếu, 唱 xướng.', '"Khẩu" như khẩu trang, nhân khẩu, khẩu hiệu.'),
  ('囗', 'enclose', 'Vẽ vòng tường vây kín bốn phía.', 'Bao kín: 国 quốc, 园 viên, 回 hồi.', '"Vi" như vây quanh, phạm vi, bao vây.'),
  ('土', 'left', 'Vẽ đống đất trên mặt đất.', 'Chữ có 土 thường về đất đai: 地 địa, 城 thành, 坐 tọa.', '"Thổ" như thổ nhưỡng, lãnh thổ, thổ dân.'),
  ('士', 'top', 'Vẽ cái rìu, biểu tượng người đàn ông có địa vị.', 'Thấy trong 壮 tráng, 声 thanh, 吉 cát.', '"Sĩ" như sĩ quan, kẻ sĩ, tiến sĩ.'),
  ('夂', 'top', 'Vẽ bàn chân chúc xuống, nghĩa là theo sau đến.', 'Nằm trên: 冬 đông, 条 điều, 各 các.', '"Truy" là đến sau, theo sau.'),
  ('夊', 'bottom', 'Vẽ bàn chân lê chậm.', 'Rất hiếm, thấy trong 夏 hạ.', '"Tuy" là đi chậm, dễ nhầm với 夂 truy.'),
  ('夕', 'left', 'Vẽ mặt trăng lưỡi liềm mới nhú, chỉ buổi chiều tối.', 'Thấy trong 多 đa, 外 ngoại, 夜 dạ.', '"Tịch" như tiệc tất niên đêm giao thừa trừ tịch.'),
  ('大', 'top', 'Vẽ người dang rộng hai tay hai chân, nghĩa là to.', 'Thấy trong 天 thiên, 太 thái, 夫 phu.', '"Đại" như đại học, vĩ đại, đại lộ.'),
  ('女', 'left', 'Vẽ người phụ nữ ngồi khoanh tay.', 'Chữ có 女 thường về nữ giới: 好 hảo, 妈 ma, 姐 tỷ.', '"Nữ" như nữ sinh, phụ nữ, nam nữ.'),
  ('子', 'left', 'Vẽ đứa bé quấn tã, hai tay giơ lên.', 'Chữ có 子 thường về con trẻ: 孩 hài, 学 học, 字 tự.', '"Tử" như tử tôn, phụ tử, thiên tử.'),
  ('宀', 'top', 'Vẽ mái nhà có nóc và hai bên tường.', 'Chữ có 宀 thường về nhà cửa: 家 gia, 安 an, 室 thất.', '"Miên" là mái nhà; ca dao gọi là bộ "mái nhà".'),
  ('寸', 'right', 'Vẽ bàn tay có vạch chỉ chỗ bắt mạch, đơn vị đo ngắn.', 'Nằm bên phải: 对 đối, 时 thời, 封 phong.', '"Thốn" như tấc, gang tấc, một tấc đất.'),
  ('小', 'top', 'Vẽ ba hạt cát nhỏ.', 'Thấy trong 少 thiểu, 尖 tiêm, 尚 thượng.', '"Tiểu" như tiểu học, tiểu thuyết, tiểu nhân.'),
  ('尢', NULL, 'Vẽ người bị què một chân, dáng nghiêng.', 'Hiếm, thấy trong 尤 vưu, 就 tựu.', '"Uông" là chân yếu, đi khập khiễng.'),
  ('尸', 'enclose', 'Vẽ người nằm duỗi, nghĩa gốc là thân xác.', 'Bao góc trên trái: 屋 ốc, 层 tằng, 局 cục.', '"Thi" như thi thể, tử thi.'),
  ('屮', 'top', 'Vẽ mầm cây vừa nhú lên khỏi đất.', 'Rất hiếm; là một nửa của 艸 thảo.', '"Triệt" là mầm non mới nhú.'),
  ('山', 'left', 'Vẽ ba ngọn núi nhô lên.', 'Chữ có 山 thường về núi: 岛 đảo, 岸 ngạn, 峰 phong.', '"Sơn" như giang sơn, sơn hà, núi non.'),
  ('巛', NULL, 'Vẽ ba dòng nước chảy song song; dạng thường dùng là 川.', 'Thấy trong 州 châu, 巢 sào.', '"Xuyên" như Tứ Xuyên, sơn xuyên.'),
  ('工', 'left', 'Vẽ cái thước hoặc đục của người thợ.', 'Thấy trong 左 tả, 功 công, 巧 xảo.', '"Công" như công nhân, công trình, thủ công.'),
  ('己', NULL, 'Vẽ sợi dây uốn khúc dùng ghi nhớ, mượn chỉ bản thân.', 'Thấy trong 记 ký, 改 cải, 纪 kỷ.', '"Kỷ" như tự kỷ, vị kỷ, tri kỷ.'),
  ('巾', 'left', 'Vẽ tấm vải treo rủ xuống.', 'Chữ có 巾 thường về vải: 布 bố, 帽 mạo, 席 tịch.', '"Cân" như khăn, khăn tay, mũ áo khăn.'),
  ('干', NULL, 'Vẽ cái chày hoặc mộc chắn, mượn làm thiên can.', 'Thấy trong 平 bình, 年 niên, 幸 hạnh.', '"Can" như can thiệp, thiên can, can dự.'),
  ('幺', 'left', 'Vẽ bó tơ nhỏ xíu, nghĩa là bé.', 'Thấy trong 幻 huyễn, 幽 u, 乡 hương.', '"Yêu" là nhỏ bé, khác "yêu" thương.'),
  ('广', 'enclose', 'Vẽ mái nhà dựa vào vách núi, hở hai bên.', 'Bao góc trên trái: 店 điếm, 庭 đình, 床 sàng.', '"Nghiễm" là mái hiên nhà rộng.'),
  ('廴', 'enclose', 'Vẽ bước chân sải dài về phía trước.', 'Bao góc dưới trái: 建 kiến, 延 diên.', '"Dẫn" là bước dài, dễ nhầm với 辶 sước.'),
  ('廾', 'bottom', 'Vẽ hai bàn tay chụm lại nâng vật lên.', 'Nằm dưới chân: 弄 lộng, 开 khai, 弃 khí.', '"Củng" như cung kính chắp tay.'),
  ('弋', NULL, 'Vẽ cây cọc có dây, dùng bắn chim rồi kéo về.', 'Thấy trong 式 thức, 武 vũ.', '"Dặc" là bắn chim bằng tên có dây.'),
  ('弓', 'left', 'Vẽ cây cung đã lắp dây.', 'Chữ có 弓 thường về cung tên: 张 trương, 弟 đệ, 引 dẫn.', '"Cung" như cung tên, cung thủ, cây cung.'),
  ('彐', 'right', 'Vẽ đầu con nhím hoặc bàn tay chụm.', 'Thấy trong 归 quy, 当 đương, 录 lục.', '"Kệ" là đầu con nhím, nay chỉ còn là nét.'),
  ('彡', 'right', 'Vẽ ba sợi lông hoặc vệt sáng nghiêng.', 'Chữ có 彡 thường về hoa văn, ánh sáng: 形 hình, 影 ảnh, 彩 thái.', '"Sam" là lông tóc dài rủ xuống.'),
  ('彳', 'left', 'Vẽ ngã tư đường, phần bên trái của chữ 行 hành.', 'Chữ có 彳 thường về đi lại: 很 ngận, 往 vãng, 得 đắc.', '"Xích" là bước chân trái, nửa trái của 行.'),
  ('心', 'bottom', 'Vẽ quả tim có buồng và mạch máu.', 'Đứng dưới là 心, bên trái đổi thành 忄: 想 tưởng, 忘 vong.', '"Tâm" như tâm lý, trung tâm, tâm hồn.'),
  ('戈', 'right', 'Vẽ cây qua, loại binh khí có lưỡi ngang.', 'Chữ có 戈 thường về vũ khí: 我 ngã, 战 chiến, 成 thành.', '"Qua" như can qua nghĩa là chiến tranh.'),
  ('戶', 'top', 'Vẽ cánh cửa một cánh, nửa của chữ 門 môn.', 'Nằm trên: 房 phòng, 所 sở, 扇 phiến.', '"Hộ" như hộ khẩu, cửa nhà, gia hộ.'),
  ('手', NULL, 'Vẽ bàn tay xòe năm ngón.', 'Đứng riêng là 手, bên trái đổi thành 扌: 打 đả, 拿 nã.', '"Thủ" như thủ công, thủ môn, cao thủ.'),
  ('支', NULL, 'Vẽ bàn tay 又 cầm cành tre, nghĩa là cành nhánh.', 'Thấy trong 枝 chi, 鼓 cổ.', '"Chi" như chi nhánh, chi phí, cành nhánh.'),
  ('攴', 'right', 'Vẽ bàn tay cầm gậy đánh khẽ; nay hầu hết viết 攵.', 'Dạng 攵: 收 thu, 改 cải, 教 giáo.', '"Phộc" là gõ nhẹ, nay chỉ gặp dạng 攵.'),
  ('文', 'top', 'Vẽ hình xăm trên ngực người, nghĩa gốc là hoa văn.', 'Thấy trong 这 giá, 齐 tề, 刘 lưu.', '"Văn" như văn hóa, văn học, văn chương.'),
  ('斗', 'right', 'Vẽ cái đấu có cán dùng đong gạo.', 'Thấy trong 料 liệu, 科 khoa.', '"Đẩu" như Bắc Đẩu, đấu gạo.'),
  ('斤', 'right', 'Vẽ cái rìu có lưỡi; cũng là đơn vị cân.', 'Thấy trong 新 tân, 断 đoạn, 所 sở.', '"Cân" như một cân, nửa cân tám lạng.'),
  ('方', 'left', 'Vẽ cái cày hai lưỡi hoặc lá cờ, nghĩa là vuông, phương hướng.', 'Thấy trong 放 phóng, 旅 lữ, 族 tộc.', '"Phương" như phương hướng, địa phương, vuông vức.'),
  ('无', NULL, 'Dạng cổ của 無, nghĩa là không có.', 'Thấy trong 既 ký, 旣.', '"Vô" như vô hình, hư vô, vô tình.'),
  ('日', 'left', 'Vẽ mặt trời tròn có chấm giữa.', 'Chữ có 日 thường về nắng, thời gian: 明 minh, 时 thời, 早 tảo.', '"Nhật" như nhật ký, nhật thực, sinh nhật.'),
  ('曰', 'top', 'Vẽ cái miệng có nét chỉ hơi thoát ra, nghĩa là nói rằng.', 'Thấy trong 書 thư, 曲 khúc, 最 tối.', '"Viết" là nói rằng, dẹt hơn 日 nhật.'),
  ('月', 'left', 'Vẽ mặt trăng khuyết.', 'Chữ có 月 là trăng hoặc là 肉 nhục biến dạng: 明 minh, 朋 bằng, 脸 kiểm.', '"Nguyệt" như nguyệt thực, tuế nguyệt, trăng.'),
  ('木', 'left', 'Vẽ cái cây có cành trên và rễ dưới.', 'Chữ có 木 thường về cây gỗ: 林 lâm, 树 thụ, 桌 trác.', '"Mộc" như thợ mộc, thảo mộc, mộc mạc.'),
  ('欠', 'right', 'Vẽ người há miệng thở ra, nghĩa gốc là ngáp.', 'Chữ có 欠 thường về hơi thở, miệng: 歌 ca, 欢 hoan, 次 thứ.', '"Khiếm" như khiếm khuyết, khiếm nhã.'),
  ('止', 'bottom', 'Vẽ bàn chân với các ngón, nghĩa gốc là chân, sau là dừng.', 'Thấy trong 步 bộ, 正 chính, 武 vũ.', '"Chỉ" như đình chỉ, cấm chỉ, ngăn chặn.'),
  ('歹', 'left', 'Vẽ khúc xương tàn còn lại, nghĩa là chết chóc.', 'Chữ có 歹 thường về chết: 死 tử, 残 tàn.', '"Đãi" như đãi độc, việc xấu xa.'),
  ('殳', 'right', 'Vẽ bàn tay cầm binh khí dài có cán.', 'Nằm bên phải: 没 một, 段 đoạn, 殺 sát.', '"Thù" là binh khí cán dài thời xưa.'),
  ('毋', NULL, 'Hình chữ 女 có nét gạch ngang, nghĩa là chớ, đừng.', 'Thấy trong 每 mỗi, 毒 độc.', '"Vô" ở đây là cấm đoán, khác 无 là không có.'),
  ('比', NULL, 'Vẽ hai người đứng cạnh nhau, nghĩa là so sánh.', 'Thấy trong 毕 tất, 皆 giai.', '"Tỷ" như tỷ lệ, so sánh, đối tỷ.'),
  ('毛', 'right', 'Vẽ túm lông hoặc chiếc lông vũ.', 'Chữ có 毛 thường về lông: 毫 hào, 毯 thảm.', '"Mao" như lông mao, mao mạch, tơ lông.'),
  ('氏', 'top', 'Vẽ lưỡi dao hoặc rễ cây, mượn chỉ dòng họ.', 'Thấy trong 民 dân, 纸 chỉ, 低 đê.', '"Thị" như họ Nguyễn thị, thị tộc.'),
  ('气', 'enclose', 'Vẽ ba luồng hơi bốc lên trời.', 'Bao bên ngoài: 氣 khí, 氧 dưỡng, 氢 khinh.', '"Khí" như không khí, khí hậu, hít thở.'),
  ('水', 'bottom', 'Vẽ dòng nước chảy có sóng hai bên.', 'Đứng dưới là 水, bên trái đổi thành 氵: 泉 tuyền, 河 hà.', '"Thủy" như thủy triều, thủy sản, phong thủy.'),
  ('火', 'bottom', 'Vẽ ngọn lửa đang cháy bốc lên.', 'Đứng dưới đổi thành 灬: 烧 thiêu, 热 nhiệt, 灯 đăng.', '"Hỏa" như hỏa hoạn, hỏa tốc, hỏa xa.'),
  ('爪', 'top', 'Vẽ bàn tay úp xuống chụp lấy vật.', 'Trên đầu đổi thành 爫: 爱 ái, 受 thụ, 采 thái.', '"Trảo" như móng vuốt, nanh vuốt.'),
  ('父', 'top', 'Vẽ bàn tay cầm cái rìu, hình ảnh người cha lao động.', 'Thấy trong 爸 ba, 爷 gia.', '"Phụ" như phụ thân, phụ mẫu, cha mẹ.'),
  ('爻', NULL, 'Vẽ hai cặp vạch chéo, là hào trong Kinh Dịch.', 'Thấy trong 学 học, 爽 sảng.', '"Hào" như hào âm hào dương trong bói Dịch.'),
  ('爿', 'left', 'Vẽ nửa trái của khúc gỗ bổ đôi; giản thể viết 丬.', 'Thấy trong 床 sàng, 状 trạng, 将 tương.', '"Tường" là mảnh gỗ, nửa trái của 片 phiến.'),
  ('片', 'left', 'Vẽ nửa phải của khúc gỗ bổ đôi, nghĩa là mảnh mỏng.', 'Thấy trong 版 bản, 牌 bài.', '"Phiến" như phiến đá, mảnh, tấm ảnh.'),
  ('牙', NULL, 'Vẽ hai hàm răng khớp vào nhau.', 'Thấy trong 邪 tà, 芽 nha.', '"Nha" như nha khoa, nha sĩ, răng nanh.'),
  ('牛', 'left', 'Vẽ đầu con trâu có hai sừng.', 'Chữ có 牛 thường về trâu bò: 物 vật, 牧 mục, 特 đặc.', '"Ngưu" như ngưu tầm ngưu, Ngưu Lang.'),
  ('犬', 'right', 'Vẽ con chó có đuôi cong.', 'Bên trái đổi thành 犭: 狗 cẩu, 猫 miêu, 猪 trư.', '"Khuyển" như khuyển mã, chó má.'),
  ('玄', 'left', 'Vẽ sợi tơ nhuộm màu đen sẫm, nghĩa là sâu kín.', 'Thấy trong 率 suất, 畜 súc.', '"Huyền" như huyền bí, huyền thoại, huyền diệu.'),
  ('玉', 'left', 'Vẽ ba miếng ngọc xâu bằng một sợi dây.', 'Vào chữ viết thành 王: 球 cầu, 玩 ngoạn, 现 hiện.', '"Ngọc" như ngọc bích, châu ngọc, bạch ngọc.'),
  ('瓜', 'right', 'Vẽ quả dưa treo trên dây leo.', 'Thấy trong 瓢 biều, 孤 cô.', '"Qua" như dưa hấu tây qua, qua điền.'),
  ('瓦', 'right', 'Vẽ viên ngói úp vào nhau trên mái.', 'Thấy trong 瓶 bình, 瓷 từ.', '"Ngõa" là ngói lợp mái nhà.'),
  ('甘', NULL, 'Vẽ cái miệng ngậm vật ngọt trong đó.', 'Thấy trong 甜 điềm, 某 mỗ.', '"Cam" như cam lộ, cam tâm, ngọt ngào.'),
  ('生', NULL, 'Vẽ mầm cây mọc lên từ mặt đất, nghĩa là sinh ra.', 'Thấy trong 性 tính, 星 tinh, 姓 tính.', '"Sinh" như sinh nhật, học sinh, sinh sống.'),
  ('用', 'right', 'Vẽ cái thùng gỗ dùng được việc.', 'Thấy trong 甭 bâng, 甩 suý.', '"Dụng" như sử dụng, công dụng, hữu dụng.'),
  ('田', 'left', 'Vẽ thửa ruộng chia thành các ô bởi bờ.', 'Chữ có 田 thường về ruộng đất: 男 nam, 界 giới, 畫 họa.', '"Điền" như điền viên, ruộng đồng, điền thổ.'),
  ('疋', 'left', 'Vẽ bàn chân, cũng dùng làm đơn vị đo vải.', 'Thấy trong 疑 nghi, 蛋 đản.', '"Sơ" là tấm vải, cũng đọc là "thất" khi đếm vải.'),
  ('疒', 'enclose', 'Vẽ người nằm trên giường bệnh, có nét chỉ mồ hôi.', 'Bao góc trên trái: 病 bệnh, 疼 đông, 痛 thống.', '"Nạch" là ốm đau, chữ nào có 疒 cũng là bệnh.'),
  ('癶', 'top', 'Vẽ hai bàn chân xoạc ra hai bên khi bước lên.', 'Nằm trên đầu: 登 đăng, 发 phát.', '"Bát" là hai chân gạt ngược, khác số tám 八.'),
  ('白', 'left', 'Vẽ hạt gạo trắng hoặc ngọn lửa trắng.', 'Chữ có 白 thường về màu trắng, rõ ràng: 的 đích, 百 bách, 皇 hoàng.', '"Bạch" như bạch mã, thanh bạch, bạch tuộc.'),
  ('皮', 'right', 'Vẽ bàn tay đang lột da thú.', 'Thấy trong 波 ba, 被 bị, 破 phá.', '"Bì" như da bì, biểu bì, bì thư.'),
  ('皿', 'bottom', 'Vẽ cái bát có chân đế.', 'Nằm dưới đáy: 盘 bàn, 盐 diêm, 益 ích.', '"Mãnh" là bát đĩa, đồ đựng.'),
  ('目', 'left', 'Vẽ con mắt dựng đứng lên.', 'Chữ có 目 thường về mắt, nhìn: 看 khán, 眼 nhãn, 睡 thụy.', '"Mục" như mục kích, danh mục, đề mục.'),
  ('矛', 'left', 'Vẽ cây giáo dài có lưỡi nhọn.', 'Thấy trong 柔 nhu, 务 vụ.', '"Mâu" như mâu thuẫn là giáo và mộc.'),
  ('矢', 'left', 'Vẽ mũi tên có đầu nhọn và đuôi lông.', 'Thấy trong 知 tri, 短 đoản, 医 y.', '"Thỉ" là mũi tên, như cung thỉ.'),
  ('石', 'left', 'Vẽ hòn đá rơi từ vách núi xuống.', 'Chữ có 石 thường về đá: 砖 chuyên, 硬 ngạnh, 碗 oản.', '"Thạch" như thạch anh, hóa thạch, bạch thạch.'),
  ('示', 'left', 'Vẽ bàn thờ tế lễ có chân, chỉ thần linh.', 'Bên trái đổi thành 礻: 神 thần, 礼 lễ, 社 xã.', '"Thị" là chỉ bảo, thị uy; liên quan thờ cúng.'),
  ('禸', NULL, 'Vẽ dấu chân thú để lại.', 'Rất hiếm, thấy trong 禽 cầm, 离 ly.', '"Nhựu" là vết chân thú, ít gặp.'),
  ('禾', 'left', 'Vẽ cây lúa trĩu bông cong xuống.', 'Chữ có 禾 thường về lúa: 秋 thu, 种 chủng, 税 thuế.', '"Hòa" là cây lúa, như hòa cốc.'),
  ('穴', 'top', 'Vẽ cái hang có cửa vào ở dưới mái.', 'Nằm trên đầu: 空 không, 窗 song, 穿 xuyên.', '"Huyệt" như huyệt mộ, hang động, điểm huyệt.'),
  ('立', 'left', 'Vẽ người đứng thẳng trên mặt đất.', 'Thấy trong 站 trạm, 亲 thân, 童 đồng.', '"Lập" như độc lập, thành lập, đứng.'),
  ('竹', 'top', 'Vẽ hai nhánh tre có lá rủ; vào chữ viết thành ⺮.', 'Nằm trên đầu: 笔 bút, 答 đáp, 第 đệ.', '"Trúc" như trúc mai, tre trúc, trúc xanh.'),
  ('米', 'left', 'Vẽ các hạt gạo rời rạc quanh một trục.', 'Chữ có 米 thường về gạo, hạt: 粉 phấn, 粗 thô, 糖 đường.', '"Mễ" như mễ cốc, gạo; Mỹ cũng viết 美.'),
  ('糸', 'left', 'Vẽ bó tơ xoắn lại; giản thể viết 纟.', 'Chữ có 纟 thường về sợi vải: 红 hồng, 线 tuyến, 纸 chỉ.', '"Mịch" là sợi tơ, như tơ tằm.'),
  ('缶', 'left', 'Vẽ cái vò sành có nắp đậy.', 'Thấy trong 缺 khuyết, 罐 quán.', '"Phẫu" là đồ sành đựng rượu.'),
  ('网', 'top', 'Vẽ tấm lưới đan mắt cáo; vào chữ viết thành 罒.', 'Nằm trên đầu: 罗 la, 罚 phạt, 置 trí.', '"Võng" như thiên la địa võng, lưới trời.'),
  ('羊', 'top', 'Vẽ đầu con dê có hai sừng cong.', 'Thấy trong 美 mỹ, 群 quần, 养 dưỡng.', '"Dương" như dê, Mùi là năm con dê.'),
  ('羽', 'top', 'Vẽ đôi cánh chim có lông.', 'Thấy trong 习 tập, 翻 phiên.', '"Vũ" như vũ mao, lông vũ, lông chim.'),
  ('老', 'top', 'Vẽ người già tóc dài chống gậy; vào chữ viết 耂.', 'Thấy trong 考 khảo, 者 giả, 孝 hiếu.', '"Lão" như lão nhân, bô lão, kính lão.'),
  ('而', NULL, 'Vẽ chòm râu dưới cằm, mượn làm liên từ.', 'Thấy trong 耐 nại, 需 nhu.', '"Nhi" như nhi hậu, "mà, và" trong văn cổ.'),
  ('耒', 'left', 'Vẽ cái cày có cán cong.', 'Thấy trong 耕 canh, 耗 hao.', '"Lỗi" là cái cày, như canh điền.'),
  ('耳', 'left', 'Vẽ vành tai người.', 'Chữ có 耳 thường về tai, nghe: 听 thính, 取 thủ, 职 chức.', '"Nhĩ" như nhĩ mục, tai mắt, trung nhĩ.'),
  ('聿', 'top', 'Vẽ bàn tay cầm cây bút lông.', 'Thấy trong 书 thư, 画 họa, 律 luật.', '"Duật" là cây bút, gốc của chữ 筆 bút.'),
  ('肉', 'left', 'Vẽ miếng thịt có thớ; vào chữ viết giống 月.', 'Chữ có 月 kiểu thịt: 肚 đỗ, 脸 kiểm, 胖 bàn.', '"Nhục" như cốt nhục, nhục thể, thịt.'),
  ('臣', 'left', 'Vẽ con mắt dựng đứng của người cúi đầu phục tùng.', 'Thấy trong 卧 ngọa, 临 lâm.', '"Thần" như quần thần, trung thần, bề tôi.'),
  ('自', 'top', 'Vẽ cái mũi người; người Hoa chỉ mũi khi nói "tôi".', 'Thấy trong 息 tức, 臭 xú, 鼻 tỵ.', '"Tự" như tự nhiên, tự do, tự mình.'),
  ('至', 'left', 'Vẽ mũi tên bắn cắm xuống đất, nghĩa là đến nơi.', 'Thấy trong 到 đáo, 致 trí, 室 thất.', '"Chí" như chí ít, đến tận, chí tử.'),
  ('臼', 'bottom', 'Vẽ cái cối giã có hạt bên trong.', 'Thấy trong 舅 cữu, 舂 thung.', '"Cữu" là cối giã gạo.'),
  ('舌', 'left', 'Vẽ cái lưỡi thè ra khỏi miệng.', 'Thấy trong 话 thoại, 甜 điềm, 乱 loạn.', '"Thiệt" như khẩu thiệt, lưỡi, thiệt chiến.'),
  ('舛', NULL, 'Vẽ hai bàn chân quay ngược chiều nhau, nghĩa là trái nghịch.', 'Hiếm, thấy trong 舞 vũ, 舜 thuấn.', '"Suyễn" là sai lệch, như sai suyễn.'),
  ('舟', 'left', 'Vẽ con thuyền có khoang.', 'Chữ có 舟 thường về thuyền: 船 thuyền, 般 ban, 航 hàng.', '"Chu" như chu xa, thuyền bè, đồng chu.'),
  ('艮', NULL, 'Vẽ con mắt ngoảnh lại không nhìn tới, nghĩa là dừng.', 'Thấy trong 很 ngận, 跟 cân, 银 ngân.', '"Cấn" là quẻ Cấn chỉ núi, sự dừng lại.'),
  ('色', NULL, 'Vẽ người cúi xuống bên người khác, nghĩa gốc là sắc mặt.', 'Hiếm làm bộ, chủ yếu đứng riêng.', '"Sắc" như sắc đẹp, màu sắc, nhan sắc.'),
  ('艸', 'top', 'Vẽ hai nhánh cỏ mọc cạnh nhau; nay viết 艹.', 'Nằm trên đầu: 花 hoa, 草 thảo, 茶 trà.', '"Thảo" như thảo mộc, thảo dược, cỏ cây.'),
  ('虍', 'enclose', 'Vẽ vằn vện trên mình con hổ.', 'Bao góc trên trái: 虎 hổ, 虚 hư, 處 xứ.', '"Hô" là vằn hổ, chữ nào có 虍 thường về hổ.'),
  ('虫', 'left', 'Vẽ con rắn hoặc sâu cuộn mình.', 'Chữ có 虫 thường về côn trùng: 蚊 văn, 蛇 xà, 蜂 phong.', '"Trùng" như côn trùng, sâu bọ, trùng độc.'),
  ('血', 'left', 'Vẽ giọt máu rơi vào bát tế lễ.', 'Thấy trong 衆 chúng, 衅 hấn.', '"Huyết" như huyết áp, xuất huyết, máu.'),
  ('行', 'enclose', 'Vẽ ngã tư đường: 彳 bên trái, 亍 bên phải.', 'Bao hai bên: 街 nhai, 衡 hành.', '"Hành" như hành trình, lữ hành, ngân hàng.'),
  ('衣', 'bottom', 'Vẽ cái áo có cổ và hai tay; bên trái đổi thành 衤.', 'Chữ có 衤 thường về áo quần: 裙 quần, 衬 sấn, 补 bổ.', '"Y" như y phục, y trang, áo quần.'),
  ('襾', 'top', 'Vẽ vật đậy úp lên trên; nay viết 覀.', 'Thấy trong 要 yếu, 覆 phúc.', '"Á" là che đậy, phần trên của chữ 要.'),
  ('見', 'right', 'Vẽ con mắt 目 đặt trên đôi chân người, nghĩa là nhìn thấy.', 'Giản thể 见: 观 quan, 觉 giác, 视 thị.', '"Kiến" như kiến thức, ý kiến, chứng kiến.'),
  ('角', 'left', 'Vẽ cái sừng thú có vân.', 'Thấy trong 解 giải, 触 xúc.', '"Giác" như giác độ, tam giác, sừng.'),
  ('言', 'left', 'Vẽ cái miệng cùng sóng âm phát ra; giản thể 讠.', 'Chữ có 讠 thường về lời nói: 说 thuyết, 话 thoại, 语 ngữ.', '"Ngôn" như ngôn ngữ, phát ngôn, tuyên ngôn.'),
  ('谷', 'left', 'Vẽ khe nước chảy ra giữa hai sườn núi.', 'Thấy trong 欲 dục, 俗 tục.', '"Cốc" như sơn cốc, thung lũng, hang cốc.'),
  ('豆', 'left', 'Vẽ cái bát có chân cao dùng tế lễ, sau mượn chỉ hạt đậu.', 'Thấy trong 短 đoản, 頭 đầu, 豐 phong.', '"Đậu" như đậu phụ, đậu nành, hạt đậu.'),
  ('豕', 'right', 'Vẽ con lợn có bụng to và đuôi ngắn.', 'Thấy trong 家 gia, 象 tượng, 逐 trục.', '"Thỉ" là con lợn; chữ 家 là lợn dưới mái nhà.'),
  ('豸', 'left', 'Vẽ con thú lưng dài đang rình mồi.', 'Thấy trong 貓 miêu, 豹 báo.', '"Trĩ" là loài thú không chân, sâu bọ.'),
  ('貝', 'left', 'Vẽ vỏ sò, thứ dùng làm tiền thời cổ; giản thể 贝.', 'Chữ có 贝 thường về tiền của: 财 tài, 贵 quý, 买 mãi.', '"Bối" như bảo bối, bối xác, vỏ sò.'),
  ('赤', NULL, 'Vẽ người đứng trên lửa lớn, màu đỏ rực.', 'Thấy trong 赦 xá, 赫 hách.', '"Xích" như xích đạo, Xích Bích, màu đỏ.'),
  ('走', 'enclose', 'Vẽ người vung tay chạy, dưới có bàn chân 止.', 'Bao góc dưới trái: 起 khởi, 超 siêu, 趣 thú.', '"Tẩu" như tẩu thoát, đào tẩu, chạy.'),
  ('足', 'left', 'Vẽ cẳng chân và bàn chân.', 'Chữ có 足 thường về chân, bước: 跑 bào, 跳 khiêu, 路 lộ.', '"Túc" như túc cầu, mãn túc, đầy đủ.'),
  ('身', 'left', 'Vẽ người có bụng to, chỉ thân mình.', 'Thấy trong 躺 thảng, 射 xạ.', '"Thân" như thân thể, bản thân, thân mình.'),
  ('車', 'left', 'Vẽ chiếc xe nhìn từ trên: thùng xe và hai bánh; giản thể 车.', 'Chữ có 车 thường về xe: 轮 luân, 软 nhuyễn, 转 chuyển.', '"Xa" như xe cộ, hỏa xa, xa lộ.'),
  ('辛', 'right', 'Vẽ con dao khắc chữ lên mặt tù nhân, nghĩa là cay đắng.', 'Thấy trong 辣 lạt, 辩 biện, 新 tân.', '"Tân" như tân khổ, cay đắng, gian tân.'),
  ('辰', NULL, 'Vẽ con sò hoặc cái cày bằng vỏ sò; mượn làm chi Thìn.', 'Thấy trong 农 nông, 唇 thần, 震 chấn.', '"Thần" như tinh thần nhật nguyệt, chi Thìn.'),
  ('辵', 'left', 'Vẽ ngã tư đường 彳 cùng bàn chân 止; nay viết 辶.', 'Chữ có 辶 thường về đi lại: 过 quá, 进 tiến, 道 đạo.', '"Sước" gọi là quai xước, chỉ sự đi lại.'),
  ('邑', 'right', 'Vẽ vùng đất có người quỳ ở dưới; bên phải viết 阝.', '阝 bên phải là ấp: 都 đô, 郊 giao, 部 bộ.', '"Ấp" như thành ấp, thôn ấp, làng xóm.'),
  ('酉', 'left', 'Vẽ vò rượu có nắp.', 'Chữ có 酉 thường về rượu, lên men: 酒 tửu, 醋 thố, 酸 toan.', '"Dậu" như chi Dậu con gà; cũng là vò rượu.'),
  ('釆', NULL, 'Vẽ móng thú tách ra, nghĩa là phân biệt rõ.', 'Thấy trong 释 thích, 番 phiên.', '"Biện" như biện biệt, phân biệt.'),
  ('里', 'left', 'Vẽ ruộng 田 trên đất 土, chỉ làng xóm và dặm đường.', 'Thấy trong 理 lý, 野 dã, 量 lượng.', '"Lý" như hương lý, dặm đường, lý trưởng.'),
  ('金', 'left', 'Vẽ các hạt kim loại vùi trong đất dưới mái; giản thể 钅.', 'Chữ có 钅 thường về kim loại: 银 ngân, 铁 thiết, 钱 tiền.', '"Kim" như kim loại, hoàng kim, kim cương.'),
  ('長', 'left', 'Vẽ người già tóc dài chống gậy; giản thể 长.', 'Thấy trong 张 trương, 帐 trướng.', '"Trường" như trường kỳ, sở trường; cũng là "trưởng".'),
  ('門', 'enclose', 'Vẽ cửa hai cánh; giản thể 门.', 'Bao bên ngoài: 问 vấn, 间 gian, 闭 bế.', '"Môn" như môn đệ, gia môn, cửa.'),
  ('阜', 'left', 'Vẽ bậc thang trên sườn đồi; bên trái viết 阝.', '阝 bên trái là phụ: 院 viện, 陈 trần, 阳 dương.', '"Phụ" là gò đất; tai trái là phụ, tai phải là ấp.'),
  ('隶', NULL, 'Vẽ bàn tay nắm lấy đuôi con thú, nghĩa là bắt kịp.', 'Thấy trong 康 khang, 逮 đãi.', '"Đãi" như đãi bộ là bắt giữ.'),
  ('隹', 'right', 'Vẽ con chim đuôi ngắn.', 'Chữ có 隹 thường về chim: 难 nan, 集 tập, 雄 hùng.', '"Chuy" là chim đuôi ngắn, khác 鳥 đuôi dài.'),
  ('雨', 'top', 'Vẽ hạt mưa rơi từ đám mây.', 'Nằm trên đầu: 雪 tuyết, 雷 lôi, 需 nhu.', '"Vũ" như vũ lượng, mưa; phong vũ biểu.'),
  ('青', 'left', 'Vẽ mầm cây mọc trên nền giếng, chỉ màu xanh non.', 'Thấy trong 清 thanh, 请 thỉnh, 情 tình.', '"Thanh" như thanh niên, thanh thiên, xanh.'),
  ('非', 'left', 'Vẽ hai cánh chim xòe ngược chiều nhau, nghĩa là trái, không.', 'Thấy trong 排 bài, 罪 tội, 悲 bi.', '"Phi" như phi pháp, phi thường, phủ định.'),
  ('面', NULL, 'Vẽ khuôn mặt có con mắt ở giữa.', 'Hiếm làm bộ, chủ yếu đứng riêng.', '"Diện" như diện mạo, thể diện, mặt.'),
  ('革', 'left', 'Vẽ tấm da thú đã căng ra thuộc kỹ.', 'Chữ có 革 thường về da: 鞋 hài, 鞭 tiên.', '"Cách" như cải cách, cách mạng; cũng là da.'),
  ('韋', 'left', 'Vẽ hai bàn chân đi vòng quanh thành, nghĩa là trái ngược; giản thể 韦.', 'Thấy trong 韩 hàn, 伟 vĩ, 围 vi.', '"Vi" như vi phạm, bao vi; cũng là da thuộc.'),
  ('韭', NULL, 'Vẽ bụi rau hẹ mọc trên mặt đất.', 'Rất hiếm, chủ yếu đứng riêng.', '"Cửu" là rau hẹ, cửu thái.'),
  ('音', 'left', 'Vẽ cái miệng 曰 có vạch chỉ âm thanh phát ra.', 'Thấy trong 意 ý, 暗 ám, 韵 vận.', '"Âm" như âm thanh, âm nhạc, phát âm.'),
  ('頁', 'right', 'Vẽ cái đầu người có tóc; giản thể 页.', 'Chữ có 页 thường về đầu, mặt: 头 đầu, 顶 đỉnh, 颜 nhan.', '"Hiệt" là cái đầu, nay dùng chỉ trang giấy.'),
  ('風', 'enclose', 'Vẽ con trùng bay trong khung gió; giản thể 风.', 'Thấy trong 飘 phiêu, 飓 cụ.', '"Phong" như phong ba, cuồng phong, gió.'),
  ('飛', NULL, 'Vẽ con chim đang xòe cánh bay lên; giản thể 飞.', 'Hiếm làm bộ, chủ yếu đứng riêng.', '"Phi" như phi cơ, phi hành, bay.'),
  ('食', 'left', 'Vẽ cái bát thức ăn có nắp; giản thể 饣.', 'Chữ có 饣 thường về ăn uống: 饭 phạn, 饿 ngạ, 馆 quán.', '"Thực" như thực phẩm, ẩm thực, lương thực.'),
  ('首', NULL, 'Vẽ cái đầu có tóc và mắt.', 'Hiếm làm bộ, thấy trong 道 đạo.', '"Thủ" như thủ đô, nguyên thủ, đứng đầu.'),
  ('香', NULL, 'Vẽ lúa 禾 trên miệng 曰, chỉ mùi thơm của gạo chín.', 'Thấy trong 馨 hinh.', '"Hương" như hương thơm, trầm hương, nhang.'),
  ('馬', 'left', 'Vẽ con ngựa có bờm, bốn chân và đuôi; giản thể 马.', 'Chữ có 马 thường về ngựa: 骑 kỵ, 驾 giá, 驴 lư.', '"Mã" như mã lực, xa mã, ngựa.'),
  ('骨', 'left', 'Vẽ khớp xương có phần thịt bám.', 'Chữ có 骨 thường về xương: 骼 cách, 髓 tủy.', '"Cốt" như cốt nhục, xương cốt, cốt truyện.'),
  ('高', NULL, 'Vẽ tòa lầu cao có mái chồng tầng.', 'Hiếm làm bộ, thấy trong 稿 cảo, 搞 cảo.', '"Cao" như cao ốc, cao thủ, cao nguyên.'),
  ('髟', 'top', 'Vẽ mái tóc dài rủ xuống dưới chữ 長.', 'Nằm trên đầu: 髮 phát, 鬍 hồ.', '"Bưu" là tóc dài, chữ nào có 髟 cũng về tóc.'),
  ('鬥', 'enclose', 'Vẽ hai người giơ tay đánh nhau.', 'Rất hiếm; giản thể gộp vào 斗.', '"Đấu" như chiến đấu, đấu tranh.'),
  ('鬯', NULL, 'Vẽ vò rượu nếp ủ thơm dùng tế lễ.', 'Rất hiếm, thấy trong 鬱 uất.', '"Sưởng" là rượu nếp cúng tế.'),
  ('鬲', NULL, 'Vẽ cái đỉnh ba chân rỗng dùng nấu.', 'Rất hiếm, thấy trong 融 dung, 隔 cách.', '"Cách" là nồi ba chân, cũng đọc "lịch".'),
  ('鬼', 'left', 'Vẽ hình người đeo mặt nạ quái dị.', 'Chữ có 鬼 thường về ma quỷ: 魂 hồn, 魔 ma.', '"Quỷ" như quỷ quái, ma quỷ, quỷ thần.'),
  ('魚', 'left', 'Vẽ con cá có đầu, vảy và đuôi; giản thể 鱼.', 'Chữ có 鱼 thường về cá: 鲜 tiên, 鲨 sa.', '"Ngư" như ngư dân, ngư nghiệp, cá.'),
  ('鳥', 'right', 'Vẽ con chim đuôi dài có mắt và chân; giản thể 鸟.', 'Chữ có 鸟 thường về chim: 鸡 kê, 鸭 áp, 鹅 nga.', '"Điểu" như điểu thú, chim chóc.'),
  ('鹵', 'left', 'Vẽ túi muối có các hạt bên trong; giản thể 卤.', 'Thấy trong 鹹 hàm, 鹼 kiềm.', '"Lỗ" là đất mặn, muối tự nhiên.'),
  ('鹿', 'enclose', 'Vẽ con hươu có gạc, bốn chân.', 'Thấy trong 麗 lệ, 麓 lộc.', '"Lộc" như hươu nai; cũng đồng âm với lộc may.'),
  ('麥', 'left', 'Vẽ cây lúa mạch có rễ; giản thể 麦.', 'Thấy trong 麵 miến, 麴 khúc.', '"Mạch" như mạch nha, lúa mạch, kiều mạch.'),
  ('麻', 'enclose', 'Vẽ hai cây gai phơi dưới mái nhà.', 'Bao góc trên trái: 摩 ma, 磨 ma.', '"Ma" như ma túy, tê ma, cây gai.'),
  ('黃', NULL, 'Vẽ người đeo ngọc bội màu vàng; giản thể 黄.', 'Thấy trong 横 hoành, 黉 hoàng.', '"Hoàng" như hoàng kim, hoàng hôn, màu vàng.'),
  ('黍', 'left', 'Vẽ cây lúa nếp có nước, chỉ loại nếp dính.', 'Rất hiếm, thấy trong 黏 niêm.', '"Thử" là lúa nếp, nếp dẻo.'),
  ('黑', 'left', 'Vẽ mặt người bị ám khói đen trên lửa.', 'Chữ có 黑 thường về đen tối: 默 mặc, 墨 mặc.', '"Hắc" như hắc ám, hắc bạch, màu đen.'),
  ('黹', NULL, 'Vẽ mũi kim thêu trên vải.', 'Rất hiếm, thấy trong 黼 phủ.', '"Chỉ" là may vá thêu thùa.'),
  ('黽', NULL, 'Vẽ con ếch nhìn từ trên xuống; giản thể 黾.', 'Rất hiếm, thấy trong 鼋 ngoan.', '"Mãnh" là con ếch, con ba ba.'),
  ('鼎', NULL, 'Vẽ cái đỉnh lớn ba chân hai tai.', 'Hiếm, chủ yếu đứng riêng.', '"Đỉnh" như đỉnh đồng, vạc, đỉnh cao.'),
  ('鼓', 'left', 'Vẽ bàn tay cầm dùi gõ vào cái trống.', 'Hiếm, chủ yếu đứng riêng.', '"Cổ" như cổ vũ, cổ động, trống.'),
  ('鼠', 'left', 'Vẽ con chuột có răng và đuôi dài.', 'Thấy trong 鼯 ngô, 鼬 dứu.', '"Thử" như Tý là chuột; khác 黍 thử lúa nếp.'),
  ('鼻', 'left', 'Vẽ cái mũi 自 cùng phần cho hơi thở qua.', 'Thấy trong 鼾 hãn.', '"Tỵ" như tỵ viêm; chi Tỵ là con rắn.'),
  ('齊', NULL, 'Vẽ ba bông lúa trổ đều ngang nhau; giản thể 齐.', 'Thấy trong 剂 tễ, 济 tế.', '"Tề" như chỉnh tề, tề tựu, đồng đều.'),
  ('齒', 'left', 'Vẽ hàm răng trong miệng; giản thể 齿.', 'Chữ có 齿 thường về răng: 龄 linh, 龈 ngân.', '"Xỉ" như nha xỉ, răng; xỉ nhục là hổ thẹn.'),
  ('龍', 'left', 'Vẽ con rồng có sừng và thân uốn; giản thể 龙.', 'Thấy trong 聋 lung, 笼 lung, 宠 sủng.', '"Long" như long phụng, thăng long, rồng.'),
  ('龜', NULL, 'Vẽ con rùa có mai và chân; giản thể 龟.', 'Hiếm, chủ yếu đứng riêng.', '"Quy" như quy giáp, rùa; cũng đọc "cưu".'),
  ('龠', NULL, 'Vẽ ống sáo nhiều lỗ buộc lại.', 'Rất hiếm, hầu như không gặp.', '"Dược" là ống sáo cổ ba lỗ.'),
  ('亻', 'left', 'Dạng đứng của 人, thu hẹp lại khi nằm bên trái chữ.', 'Chữ có 亻 thường về người: 你 nhĩ, 他 tha, 作 tác.', '"Nhân" như nhân viên; nhìn như người đứng nghiêng.'),
  ('刂', 'right', 'Dạng đứng của 刀, lưỡi dao dựng bên phải chữ.', 'Chữ có 刂 thường về cắt chém: 到 đáo, 刻 khắc, 别 biệt.', '"Đao" như đao kiếm; hai nét như lưỡi dao dựng.'),
  ('忄', 'left', 'Dạng đứng của 心, quả tim thu gọn bên trái.', 'Chữ có 忄 thường về cảm xúc: 快 khoái, 怕 phạ, 情 tình.', '"Tâm" như tâm trạng; chữ nào có 忄 đều về lòng người.'),
  ('扌', 'left', 'Dạng đứng của 手, bàn tay thu gọn bên trái.', 'Chữ có 扌 thường là động tác tay: 打 đả, 拿 nã, 提 đề.', '"Thủ" như thủ công; gọi vui là "tài gảy".'),
  ('氵', 'left', 'Dạng rút gọn của 水, ba giọt nước bên trái chữ.', 'Chữ có 氵 thường về nước: 河 hà, 海 hải, 洗 tẩy.', '"Thủy" như thủy triều; ba chấm thủy dễ nhận nhất.'),
  ('灬', 'bottom', 'Dạng nằm của 火, bốn chấm là ngọn lửa dưới đáy chữ.', 'Chữ có 灬 thường về nấu nướng, nhiệt: 热 nhiệt, 煮 chử, 照 chiếu.', '"Hỏa" như hỏa lò; bốn chấm là lửa liếm đáy nồi.'),
  ('爫', 'top', 'Dạng nằm của 爪, bàn tay úp chụp từ trên xuống.', 'Nằm trên đầu: 爱 ái, 受 thụ, 爬 ba.', '"Trảo" như móng vuốt chụp xuống từ trên.'),
  ('犭', 'left', 'Dạng đứng của 犬, con chó thu gọn bên trái.', 'Chữ có 犭 thường về thú: 狗 cẩu, 猫 miêu, 狼 lang.', '"Khuyển" như khuyển mã; thấy 犭 là loài thú bốn chân.'),
  ('礻', 'left', 'Dạng đứng của 示, bàn thờ thu gọn bên trái.', 'Chữ có 礻 thường về thờ cúng, phúc họa: 神 thần, 礼 lễ, 福 phúc.', '"Thị" là bàn thờ; đừng nhầm với 衤 y chỉ áo.'),
  ('罒', 'top', 'Dạng nằm của 网, tấm lưới đặt ngang trên đầu chữ.', 'Nằm trên đầu: 罗 la, 置 trí, 罚 phạt.', '"Võng" là lưới; nhìn như 四 nằm ngang.'),
  ('衤', 'left', 'Dạng đứng của 衣, cái áo thu gọn bên trái.', 'Chữ có 衤 thường về áo quần: 衬 sấn, 裤 khố, 补 bổ.', '"Y" như y phục; nhiều hơn 礻 một chấm.'),
  ('艹', 'top', 'Dạng rút gọn của 艸, hai nhánh cỏ trên đầu chữ.', 'Chữ có 艹 thường về cây cỏ: 花 hoa, 草 thảo, 菜 thái.', '"Thảo" như thảo dược; gọi là thảo đầu, đội cỏ trên đầu.'),
  ('辶', 'left', 'Dạng rút gọn của 辵, đường đi ôm lấy góc dưới trái.', 'Chữ có 辶 thường về đi lại: 走 tẩu, 过 quá, 进 tiến, 送 tống.', '"Sước" gọi là quai xước; thấy 辶 là có chuyển động.'),
  ('阝', 'left', 'Bên trái là 阜 gò đất, bên phải là 邑 vùng đất; hai gốc khác nhau, viết giống nhau.', 'Trái: 院 viện, 阳 dương. Phải: 都 đô, 部 bộ.', 'Mẹo: tai trái là đồi núi, tai phải là làng xóm.'),
  ('⺮', 'top', 'Dạng rút gọn của 竹, hai nhánh tre trên đầu chữ.', 'Chữ có ⺮ thường về tre, đồ tre: 笔 bút, 筷 khoái, 箱 tương.', '"Trúc" như tre trúc; bút 笔 là tre có lông.'),
  ('王', 'left', 'Dạng rút gọn của 玉 khi đứng bên trái, mất dấu chấm.', 'Chữ có 王 bên trái thường về ngọc: 球 cầu, 现 hiện, 玩 ngoạn.', 'Mẹo: 王 đứng riêng là vua, đứng bên trái là ngọc.'),
  ('耂', 'top', 'Dạng rút gọn của 老, người già trên đầu chữ.', 'Nằm trên đầu: 考 khảo, 者 giả, 孝 hiếu.', '"Lão" như bô lão, kính lão đắc thọ.'),
  ('覀', 'top', 'Dạng nằm của 襾, vật đậy úp trên đầu chữ.', 'Nằm trên đầu: 要 yếu, 票 phiếu, 西 tây.', '"Á" là nắp đậy; nhìn gần giống 西 tây.'),
  ('攵', 'right', 'Dạng rút gọn của 攴, tay cầm gậy đánh khẽ bên phải.', 'Chữ có 攵 thường về tác động: 收 thu, 改 cải, 教 giáo, 放 phóng.', '"Phộc" gọi là phản văn, như chữ 文 viết ngược.'),
  ('丬', 'left', 'Dạng giản thể của 爿, nửa trái khúc gỗ.', 'Thấy trong 状 trạng, 将 tương, 壮 tráng.', '"Tường" là mảnh gỗ; đối xứng với 片 phiến.'),
  ('牜', 'left', 'Dạng đứng của 牛, con trâu thu gọn bên trái.', 'Chữ có 牜 thường về trâu bò: 物 vật, 牧 mục, 特 đặc.', '"Ngưu" như ngưu tầm ngưu, mã tầm mã.'),
  ('讠', 'left', 'Dạng giản thể của 言, lời nói thu còn hai nét.', 'Chữ có 讠 thường về nói năng: 说 thuyết, 话 thoại, 语 ngữ, 谢 tạ.', '"Ngôn" như ngôn ngữ, phát ngôn.'),
  ('钅', 'left', 'Dạng giản thể của 金, kim loại thu gọn bên trái.', 'Chữ có 钅 thường về kim loại: 银 ngân, 铁 thiết, 钟 chung.', '"Kim" như kim loại, hoàng kim.'),
  ('饣', 'left', 'Dạng giản thể của 食, bát cơm thu gọn bên trái.', 'Chữ có 饣 thường về ăn uống: 饭 phạn, 饺 giáo, 饿 ngạ.', '"Thực" như thực phẩm, ẩm thực.'),
  ('纟', 'left', 'Dạng giản thể của 糸, bó tơ thu gọn bên trái.', 'Chữ có 纟 thường về sợi vải: 红 hồng, 纸 chỉ, 给 cấp, 经 kinh.', '"Mịch" là sợi tơ; thấy 纟 là liên quan vải vóc.'),
  ('贝', 'left', 'Dạng giản thể của 貝, vỏ sò làm tiền.', 'Chữ có 贝 thường về tiền bạc: 财 tài, 货 hóa, 买 mãi, 贵 quý.', '"Bối" như bảo bối; vỏ sò là tiền thời cổ.'),
  ('见', 'right', 'Dạng giản thể của 見, nhìn thấy.', 'Thấy trong 观 quan, 觉 giác, 视 thị.', '"Kiến" như ý kiến, kiến thức.'),
  ('车', 'left', 'Dạng giản thể của 車, chiếc xe.', 'Chữ có 车 thường về xe: 轮 luân, 轻 khinh, 转 chuyển.', '"Xa" như xe cộ, hỏa xa.'),
  ('门', 'enclose', 'Dạng giản thể của 門, cửa hai cánh.', 'Bao bên ngoài: 问 vấn, 间 gian, 闹 náo.', '"Môn" như môn đệ, gia môn.'),
  ('页', 'right', 'Dạng giản thể của 頁, cái đầu người.', 'Chữ có 页 thường về đầu mặt: 顶 đỉnh, 颜 nhan, 题 đề.', '"Hiệt" là đầu; nay dùng chỉ trang giấy.'),
  ('风', 'enclose', 'Dạng giản thể của 風, gió.', 'Thấy trong 飘 phiêu, 飒 táp.', '"Phong" như phong ba, gió bão.'),
  ('飞', NULL, 'Dạng giản thể của 飛, chim bay.', 'Hiếm làm bộ, chủ yếu đứng riêng.', '"Phi" như phi cơ, phi hành.'),
  ('马', 'left', 'Dạng giản thể của 馬, con ngựa.', 'Chữ có 马 thường về ngựa: 骑 kỵ, 驾 giá, 妈 ma.', '"Mã" như mã lực, xa mã.'),
  ('鱼', 'left', 'Dạng giản thể của 魚, con cá.', 'Chữ có 鱼 thường về cá: 鲜 tiên, 鲤 lý.', '"Ngư" như ngư dân, ngư nghiệp.'),
  ('鸟', 'right', 'Dạng giản thể của 鳥, con chim đuôi dài.', 'Chữ có 鸟 thường về chim: 鸡 kê, 鸭 áp, 鹅 nga.', '"Điểu" như điểu thú, chim chóc.'),
  ('长', 'left', 'Dạng giản thể của 長, dài và lớn lên.', 'Thấy trong 张 trương, 帐 trướng, 胀 trướng.', '"Trường" như trường kỳ; cũng đọc "trưởng".'),
  ('韦', 'left', 'Dạng giản thể của 韋, da thuộc.', 'Thấy trong 韩 hàn, 伟 vĩ, 违 vi.', '"Vi" như vi phạm, bao vi.'),
  ('齿', 'left', 'Dạng giản thể của 齒, hàm răng.', 'Chữ có 齿 thường về răng: 龄 linh, 龈 ngân.', '"Xỉ" như nha xỉ, răng miệng.'),
  ('龙', 'left', 'Dạng giản thể của 龍, con rồng.', 'Thấy trong 笼 lung, 宠 sủng, 垄 lũng.', '"Long" như long phụng, thăng long.'),
  ('龟', NULL, 'Dạng giản thể của 龜, con rùa.', 'Hiếm, chủ yếu đứng riêng.', '"Quy" như quy giáp, rùa vàng.'),
