  ('卤', 'left', 'Dạng giản thể của 鹵, đất mặn và muối.', 'Thấy trong 鹾 ta.', '"Lỗ" là muối mặn, nước kho.'),
  ('黄', NULL, 'Dạng giản thể của 黃, màu vàng.', 'Thấy trong 横 hoành, 璜 hoàng.', '"Hoàng" như hoàng kim, hoàng hôn.'),
